    r2.x = candidate->m[2][0]; r2.y = candidate->m[2][1]; r2.z = candidate->m[2][2];

    /* Step 1: Normalize row 0 as x */
    if (adcs_vec3_normalize(&r0, ADCS_EPS_NORM, &x) != ADCS_OK) {
        *repaired = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }

    /* Step 2: Remove projection of row 1 from x and normalize remainder as y */
    /* Projection coefficient of r1 onto normalized x is dot(r1, x) */
    dot_val = adcs_vec3_dot(&r1, &x);
    scaled_x = adcs_vec3_scale(&x, dot_val);
    temp = adcs_vec3_sub(&r1, &scaled_x);

    if (adcs_vec3_normalize(&temp, ADCS_EPS_NORM, &y) != ADCS_OK) {
        *repaired = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }

    /* Step 3: Set z = x cross y */
    z = adcs_vec3_cross(&x, &y);

    /* Step 4: Recompute y = z cross x to ensure strict right-handed orthogonality */
    y = adcs_vec3_cross(&z, &x);

    /* Store x, y, z as rows in repaired matrix */
    repaired->m[0][0] = x.x; repaired->m[0][1] = x.y; repaired->m[0][2] = x.z;
    repaired->m[1][0] = y.x; repaired->m[1][1] = y.y; repaired->m[1][2] = y.z;
    repaired->m[2][0] = z.x; repaired->m[2][1] = z.y; repaired->m[2][2] = z.z;

    /* Calculate correction_norm: Frobenius norm of (repaired - candidate) */
    diff_sq_sum = 0.0;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            double diff = repaired->m[i][j] - candidate->m[i][j];
            diff_sq_sum += diff * diff;
        }
    }
    *correction_norm = sqrt(diff_sq_sum);

    return ADCS_OK;
}
